package org.sleepwell.app;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class SonarEpochsTest {
 static SonarObservation frame(long elapsed,Double movement,SonarFrame.Quality quality){return new SonarObservation(elapsed*1000000L,(elapsed+40)*1000000L,new SonarFrame(0,40,movement,quality,12,.8));}
 static final class Row {final long from,to,active;final Double value;final String quality;final int samples;Row(long from,long to,Double value,String quality,int samples,long active){this.from=from;this.to=to;this.value=value;this.quality=quality;this.samples=samples;this.active=active;}}
 @Test public void bootCaptureProjectsToWallAndWarmupMissingNeverBecomesZero()throws Exception{List<Row> rows=new ArrayList<>();SonarEpochs epochs=new SonarEpochs(100000,1000,1000,0,(a,b,v,q,n,active)->rows.add(new Row(a,b,v,q,n,active)));epochs.add(frame(1200,0d,SonarFrame.Quality.VALID),6000);epochs.finish(6000,SonarFrame.Quality.NO_ECHO);assertEquals(3,rows.size());assertEquals(100000,rows.get(0).from);assertEquals("CALIBRATING",rows.get(0).quality);assertNull(rows.get(0).value);assertEquals(0,rows.get(1).value,0);assertEquals(1,rows.get(1).samples);assertEquals(100200,rows.get(1).from);assertNull(rows.get(2).value);assertEquals("NO_ECHO",rows.get(2).quality);assertEquals(5000,rows.get(2).active);}
 @Test public void boundedMeansDoNotSplitRealFramesOrAverageAcrossMissingQuality()throws Exception{List<Row> rows=new ArrayList<>();SonarEpochs epochs=new SonarEpochs(100000,1000,1000,0,(a,b,v,q,n,active)->rows.add(new Row(a,b,v,q,n,active)));for(int n=0;n<300;n++)epochs.add(frame(1000+n*40,n==130?null:(double)(n%2),n==130?SonarFrame.Quality.CLIPPED:SonarFrame.Quality.VALID),14000);epochs.finish(13000,SonarFrame.Quality.UNAVAILABLE);long cursor=100000;boolean clipped=false;for(Row row:rows){assertEquals(cursor,row.from);assertTrue(row.to-row.from<=5000);cursor=row.to;if(row.quality.equals("CLIPPED")){clipped=true;assertNull(row.value);}else{assertNotNull(row.value);assertTrue(row.samples>0);assertTrue(row.value>=0&&row.value<=1);}}assertTrue(clipped);assertEquals(112000,cursor);}
 @Test public void lateCaptureCannotRetroactivelyReplaceDurableMissingEvidence()throws Exception{List<Row> rows=new ArrayList<>();SonarEpochs epochs=new SonarEpochs(100000,1000,1000,0,(a,b,v,q,n,active)->rows.add(new Row(a,b,v,q,n,active)));epochs.through(7000,SonarFrame.Quality.UNAVAILABLE);assertThrows(IllegalStateException.class,()->epochs.add(frame(2000,1d,SonarFrame.Quality.VALID),8000));assertEquals(1,rows.size());assertNull(rows.get(0).value);assertEquals(105000,rows.get(0).to);}
 @Test public void resumeUsesSameWallAnchorButExcludesPausedGapFromActive()throws Exception{List<Row> rows=new ArrayList<>();SonarEpochs epochs=new SonarEpochs(100000,1000,10000,4000,(a,b,v,q,n,active)->rows.add(new Row(a,b,v,q,n,active)));epochs.add(frame(10000,.25,SonarFrame.Quality.VALID),11000);epochs.finish(11000,SonarFrame.Quality.UNAVAILABLE);assertEquals(109000,rows.get(0).from);assertEquals(5000,rows.get(rows.size()-1).active);assertEquals(110000,rows.get(rows.size()-1).to);}
}
